const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const recordCache=new Map();
const isOpen=q=>!['Geklärt','Archiviert'].includes(q.status);
const reconcileCount=()=> (impactData.reconciliations||[]).reduce((n,b)=>n+b.items.length,0);
let impactData={findings:[],jobs:[],pending:0};
let G,questions=[],current={page:'dashboard',id:'mandraya'},topic,exploration,chatState,models=[],history=[],chatBusy=false,aborter=null,renderSerial=0;
const title=id=>G.nodes.find(n=>n.id===id)?.title||id;
const stageClass=s=>({'Ungeprüft':'unchecked','In Bearbeitung':'working','Klärung nötig':'clarify','Ausgearbeitet':'ready'}[s]||'unchecked');
const stamp=s=>new Date(s).toLocaleString('de-DE');
const rich=s=>esc(s).split(/\n\s*\n/).map(p=>'<p>'+p.replace(/^#{1,4} +(.+)$/gm,'<strong>$1</strong>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')+'</p>').join('');
const lock='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5Z"/></svg>';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',7000)}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const p=await r.json();if(!r.ok)throw Error(p.detail||'Anfrage fehlgeschlagen');return p}
async function safely(f){try{await f()}catch(e){toast(e.message)}}
function go(page,id=''){location.hash=page+'/'+id}
async function refreshData(){[G,questions,impactData]=await Promise.all([api('graph'),api('work-questions'),api('impact')]);$('#roots').innerHTML=G.nodes.filter(n=>!n.parent).map(n=>`<button data-dashboard="${esc(n.id)}" class="${current.page==='dashboard'&&current.id===n.id?'active':''}">${esc(n.title)}</button>`).join('');$('#sourcecount').textContent=G.source_count;$('#impactcount').textContent=impactData.findings.length+reconcileCount();$('#questioncount').textContent=questions.filter(q=>isOpen(q)).length}
async function route(preservePosition=false){const serial=++renderSerial;const [page,id]=location.hash.slice(1).split('/');current={page:page||'dashboard',id:decodeURIComponent(id||'mandraya')};await refreshData();if(serial!==renderSerial)return;$('#canvas').hidden=true;$('#scene').innerHTML='<p class="muted">Arbeitsstand wird geladen …</p>';$('#viewactions').innerHTML='';$('#breadcrumb').innerHTML='';$('#main').classList.remove('workshop','question-workshop');$('#viewsubtitle').textContent='';if(!preservePosition){$('#main').scrollTop=0;window.scrollTo(0,0);}
 if(current.page==='dashboard')dashboard(current.id);
 else if(current.page==='topic'){topic=await api('workbench/'+current.id);if(serial===renderSerial)renderTopic()}
 else if(current.page==='workshop'){exploration=await api('explorations/'+current.id);topic=await api('workbench/'+exploration.node_id);[chatState,history]=await Promise.all([api('chatgpt/status'),api('chat/'+topic.id+'?session_id='+exploration.id)]);if(serial===renderSerial)await renderWorkshop()}
 else await utility(current.page);
}
function header(kicker,name,subtitle,actions=''){$('#breadcrumb').innerHTML=kicker.includes('<button')?kicker:'';$('#breadcrumb').hidden=!kicker.includes('<button');$('#viewtitle').textContent=name;$('#viewsubtitle').textContent=subtitle;$('#viewactions').innerHTML=actions}
function branchIds(id){const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const n of G.nodes)if(ids.has(n.parent)&&!ids.has(n.id)){ids.add(n.id);changed=true}}return ids}
function branchQuestions(id){const ids=branchIds(id);return questions.filter(q=>isOpen(q)&&ids.has(q.node_id))}
function branchFindings(id){const ids=branchIds(id);return impactData.findings.filter(f=>ids.has(f.node_id))}
function dashboard(id){const n=G.nodes.find(n=>n.id===id)||G.nodes[0];header('PROJEKTÜBERSICHT',n.title,'Einmal anklicken: Themenstand öffnen. Über „Unterthemen“ tiefer ins Projekt gehen.',n.parent?`<button data-dashboard="${esc(n.parent)}">Eine Ebene zurück</button>`:'');$('#scene').innerHTML='<div class="legend"><span><i class="dot unchecked"></i>Ungeprüft</span><span><i class="dot working"></i>In Bearbeitung</span><span><i class="dot clarify"></i>Klärung nötig</span><span><i class="dot ready"></i>Ausgearbeitet</span><span>Beschlüsse und Fragen siehst du im Themenstand.</span></div>';$('#canvas').hidden=false;
 const children=G.nodes.filter(x=>x.parent===n.id),shown=[n,...children],pos={};shown.forEach((x,i)=>pos[x.id]=i?{x:i%2?45:355,y:175+Math.floor((i-1)/2)*155}:{x:195,y:24});const height=210+Math.ceil(children.length/2)*155;$('#nodes').style.minHeight=height+'px';$('#connections').style.height=height+'px';$('#nodes').innerHTML=shown.map(x=>{const branch=branchQuestions(x.id),count=branch.length,inherited=branch.some(q=>q.node_id!==x.id),findings=branchFindings(x.id).length+branchReconciliations(x.id).reduce((n,b)=>n+b.items.length,0);return `<div class="node" data-map-id="${esc(x.id)}"><button class="node-open" data-topic="${esc(x.id)}"><strong>${x.locked?lock:''}${esc(x.title)}</strong><small><i class="dot ${stageClass(x.stage)}"></i>${esc(x.stage)}</small><small>${esc(x.scope)}${count?' · '+count+' offene Frage'+(count===1?'':'n')+(inherited?' inkl. Unterthemen':''):''}${findings?' · '+findings+' KI-Prüfhinweis'+(findings===1?'':'e'):''}</small></button>${G.nodes.some(y=>y.parent===x.id)?`<button class="node-expand" data-dashboard="${esc(x.id)}">Unterthemen →</button>`:''}</div>`}).join('');const heights={};$('#nodes').querySelectorAll('[data-map-id]').forEach(el=>heights[el.dataset.mapId]=el.getBoundingClientRect().height);let rowY=24+heights[n.id]+24;for(let i=0;i<children.length;i+=2){const row=children.slice(i,i+2);row.forEach(x=>pos[x.id].y=rowY);rowY+=Math.max(...row.map(x=>heights[x.id]))+22}$('#nodes').style.minHeight=(rowY+24)+'px';$('#connections').style.height=(rowY+24)+'px';$('#nodes').querySelectorAll('[data-map-id]').forEach(el=>{el.style.left=pos[el.dataset.mapId].x+'px';el.style.top=pos[el.dataset.mapId].y+'px'});$('#connections').innerHTML=children.map(x=>`<path d="M310 ${24+heights[n.id]} C310 ${pos[x.id].y-30},${pos[x.id].x+115} ${pos[x.id].y-30},${pos[x.id].x+115} ${pos[x.id].y}" fill="none" stroke="#56636b" stroke-width="1.3"/>`).join('')}
const topicCrumb=()=>`<button class="text-button" data-dashboard="${esc(topic.parent||topic.id)}">Projektübersicht</button><span> / ${esc(topic.scope)}</span>`;
function sourceLinks(evidence){const items=(typeof evidence==='string'?JSON.parse(evidence||'[]'):evidence||[]).filter(s=>s.source_id);return items.length?`<details class="evidence"><summary>Verwendete Quellen (${items.length})</summary>${items.map(s=>`<button class="list-row" data-source="${esc(s.source_id)}" data-version="${s.version_id}"><strong>${esc(s.title)}</strong><small>Zitierte Fassung ${s.version_id}</small></button>`).join('')}</details>`:'<p class="small">Keine zusätzlichen Quellenbelege gespeichert.</p>'}
function questionRow(q){return `<article class="entry"><h3>${esc(q.question)}</h3><p class="small">${esc(q.status)} · ${esc(title(q.node_id))}</p><p>${esc(q.reason)}</p>${q.answer?`<p class="prose">Ergebnis: ${esc(q.answer)}</p>`:''}<p class="small">Entstanden bei ${esc(title(q.origin_node))}</p><div class="actions">${isOpen(q)?`<button data-clarify="${esc(q.id)}" class="primary">Mit KI klären</button>`:''}<button data-question="${esc(q.id)}">Frage ansehen</button><button data-topic="${esc(q.node_id)}">Zum betroffenen Thema</button>${q.session_id?`<button data-workshop="${esc(q.session_id)}">Ursprüngliche Diskussion</button>`:''}</div></article>`}
const reconcileAction={resolve:'Frage klären',revise:'Offenen Rest präzisieren',archive:'Überholte Frage archivieren',update:'Arbeitsfassung aktualisieren'};
function branchReconciliations(id){const ids=branchIds(id);return (impactData.reconciliations||[]).filter(b=>b.items.some(i=>ids.has(i.kind==='question'?i.before.node_id:i.target_id)))}
function reconcileRow(b){return `<article class="entry"><h3>Bestehenden Stand abgleichen (${b.items.length})</h3><p>${esc(b.summary)}</p>${b.stale?'<p class="notice">Die Grundlage hat sich geändert. Bitte den Abgleich neu erstellen lassen.</p>':''}<ul>${b.items.map(i=>`<li>${esc(reconcileAction[i.action])} · ${esc(title(i.kind==='question'?i.before.node_id:i.target_id))}${i.kind==='question'?': '+esc(i.before.question):''}</li>`).join('')}</ul><div class="actions"><button data-reconcile="${b.id}" class="primary">Änderungen gemeinsam prüfen</button>${b.stale?'<button data-impact-check="mandraya">Neu prüfen</button>':''}</div></article>`}
function showReconciliation(id){const b=(impactData.reconciliations||[]).find(b=>b.id===id);if(!b)throw Error('Abgleich nicht mehr verfügbar. Bitte aktualisieren.');modal('Folgen des Beschlusses prüfen',`<p>Die KI hat Änderungen am bestehenden Stand vorbereitet. Wähle nur die Ergebnisse aus, die du geprüft hast. Es entsteht kein neuer Beschluss.</p>${b.stale?'<p class="notice">Die Grundlage ist veraltet. Bitte neu prüfen lassen.</p>':''}<form id="reconcile-form">${b.items.map(i=>`<section class="section" data-reconcile-item="${i.id}"><h3>${esc(reconcileAction[i.action])} · ${esc(title(i.kind==='question'?i.before.node_id:i.target_id))}</h3><label class="check"><input type="checkbox" class="take" ${b.stale?'disabled':''}> Diese Änderung übernehmen</label><p>${esc(i.reason)}</p>${i.kind==='question'?`<p class="prose"><strong>Bisherige Frage:</strong> ${esc(i.before.question)}</p>${i.before.answer?`<details><summary>Bisherige Klärung</summary><p class="prose">${esc(i.before.answer)}</p></details>`:''}${i.action==='revise'?`<label>Verbleibende offene Frage<textarea class="reconcile-question short-text">${esc(i.after.question)}</textarea></label>`:''}<label>${i.action==='revise'?'Was bereits geklärt ist':i.action==='archive'?'Warum die Frage gegenstandslos ist':'Antwort aus dem aktuellen Beschluss'}<textarea class="reconcile-answer short-text">${esc(i.after.answer)}</textarea></label><p class="small">Nach Übernahme: ${esc(i.after.status)}. Frage und Verlauf bleiben erhalten.</p>`:`<details><summary>Bisherige Arbeitsfassung vergleichen</summary><div class="prose">${esc(i.before.content)}</div></details><label>Vorgeschlagene vollständige Arbeitsfassung<textarea class="reconcile-content">${esc(i.after.content)}</textarea></label><p class="small">Die bisherige Fassung wird archiviert. Beschlossene Aussagen bleiben erhalten.</p>`}${findingEvidence({evidence:JSON.stringify(i.evidence)})}</section>`).join('')}<label for="reconcile-reason">Kommentar zur Übernahme (optional)</label><input id="reconcile-reason" placeholder="Zum Beispiel: Warum du vom Vorschlag abweichst"><div class="actions"><button type="button" data-reconcile-apply="${b.id}" class="primary" disabled>Ausgewählte Änderungen übernehmen</button><button type="button" data-reconcile-reject="${b.id}">Gesamten Abgleich verwerfen</button><button type="button" id="modal-close-secondary">Später prüfen</button></div></form>`);$('#reconcile-form').onchange=()=>{ $('[data-reconcile-apply]').disabled=b.stale||!$('#reconcile-form').querySelector('.take:checked')};$('#reconcile-form').onsubmit=e=>e.preventDefault()}
function findingEvidence(f){const ev=JSON.parse(f.evidence||'[]'),nodes=ev.filter(e=>e.node_id&&!e.statement_id),decisions=ev.filter(e=>e.statement_id);return `${decisions.length?`<details class="evidence"><summary>Maßgebliche Beschlüsse (${decisions.length})</summary>${decisions.map(d=>`<article class="entry"><p class="prose">${esc(d.content)}</p><p class="small">Beschlussfassung ${d.version} · ${esc(title(d.node_id))}</p></article>`).join('')}</details>`:''}${nodes.length?`<details class="evidence"><summary>Bereitgestellte Themenstände (${nodes.length})</summary>${nodes.map(n=>`<button class="list-row" data-topic="${esc(n.node_id)}"><strong>${esc(n.title||title(n.node_id))}</strong><small>Grundlage: Fassung ${n.version} · aktuellen Themenstand öffnen</small></button>`).join('')}</details>`:''}${ev.some(e=>e.source_id)?sourceLinks(ev):''}`}
function findingRow(f){return `<article class="entry"><h3>${esc(f.question)}</h3><p class="small">KI-Prüfhinweis · ${esc(title(f.node_id))} · ${esc(f.status)}</p>${f.stale?'<p class="notice">Die Grundlage hat sich inzwischen geändert. Vor dem Speichern erneut prüfen oder mit der KI besprechen.</p>':''}<p>${esc(f.reason)}</p><p class="small">Auswirkung aus ${esc(title(f.origin_node))}. Noch nicht als offene Frage gespeichert.</p>${findingEvidence(f)}<div class="actions"><button data-impact-discuss="${f.id}" class="primary">Mit KI besprechen</button><button data-impact-review="${f.id}" ${f.stale?'disabled':''}>Als offene Frage speichern</button>${f.stale?`<button data-impact-check="${esc(f.node_id)}">Neu prüfen</button>`:''}<button data-impact-reject="${f.id}">Verwerfen</button></div></article>`}
function impactSection(id){const bs=branchReconciliations(id);const fs=branchFindings(id);return `<section class="section"><h2>KI-Prüfhinweise${fs.length?' ('+fs.length+')':''}</h2>${impactData.pending?'<p class="small">Die automatische Projektprüfung hat noch '+impactData.pending+' offenen Auftrag bzw. wartet auf eine Verbindung.</p>':''}${bs.map(reconcileRow).join('')}${fs.map(findingRow).join('')||(bs.length?'':'<p class="muted">Keine offenen KI-Prüfhinweise für dieses Thema. Das ist kein Vollständigkeitsnachweis.</p>')}<button data-view="impact">Projektweite Prüfung ansehen</button></section>`}
function renderTopic(){header(topicCrumb(),topic.title,'Verstehe die Grundlage. Entscheide dann, wo du weiterarbeiten möchtest.',`<button data-begin="${esc(topic.id)}" class="primary">Werkstatt öffnen</button>`);const brief=topic.brief;const activeSources=topic.sources.filter(s=>s.policy?.status==='Aktuell'||!s.policy);const archivedSources=topic.sources.filter(s=>s.policy&&s.policy.status!=='Aktuell');
 $('#scene').innerHTML=`<div class="topic-grid"><section class="topic-primary"><section class="section"><div class="section-heading"><h2>Der Stand auf einen Blick</h2><button id="brief" ${chatBusy?'disabled':''}>${brief?'KI-Überblick aktualisieren':'KI-Überblick erstellen'}</button></div>${brief?`${brief.stale?'<p class="notice">Seit diesem Überblick hat sich das Projekt geändert. Vor weiteren Entscheidungen bitte aktualisieren.</p>':''}<div class="rich">${rich(brief.content)}</div><p class="small">KI-Einordnung · ${stamp(brief.at)} · keine vollständige Quellenprüfung</p>${sourceLinks(brief.evidence)}`:'<p class="muted">Noch kein KI-Überblick erstellt. Die folgenden Abschnitte zeigen die gespeicherte Grundlage unmittelbar.</p>'}<p id="brief-status" role="status" class="small"></p></section>
 <section class="section"><div class="section-heading"><h2>Beschlossene Aussagen</h2><button id="new-statement">Aussage festhalten</button></div><p class="small">Eine Aussage kann gesetzt sein, während ihr am übrigen Thema weiterarbeitet.</p>${topic.locked?`<article class="entry"><p class="eyebrow">Bisherige Gesamtfassung geschützt</p><div class="prose">${esc(topic.content)}</div><button id="edit-concept">Gesamtfassung ansehen / wieder öffnen</button></article>`:''}${topic.statements.length?topic.statements.map(s=>`<article class="entry"><p class="eyebrow">${esc(s.status)} · Fassung ${s.version}</p><div class="prose">${esc(s.content)}</div><button data-statement="${esc(s.id)}">${s.status==='Beschlossen'?'Beschluss ansehen':'Aussage bearbeiten'}</button></article>`).join(''):!topic.locked?'<p class="muted">Noch keine einzelnen Aussagen beschlossen.</p>':''}</section>
 <section class="section"><div class="section-heading"><h2>Gemeinsame Arbeitsfassung</h2><button id="edit-concept">Fassung bearbeiten</button></div><p class="small">Fassung ${topic.version} · ${esc(topic.stage)}</p>${topic.foundation?`<p class="notice">${topic.content===topic.foundation.content?'Vorhandene Unterlagen sind als Quellenstand eingearbeitet.':'Zusätzlich liegt ein Quellenstand vor; deine bestehende Arbeitsfassung wurde bewahrt.'} Fachlich noch nicht freigegeben; keine neuen Beschlüsse.</p>${topic.content!==topic.foundation.content?`<details><summary>Zusammengeführten Quellenstand ansehen</summary><div class="prose">${esc(topic.foundation.content)}</div></details>`:''}${sourceLinks(topic.foundation.evidence)}`:''}<div class="prose">${esc(topic.content||'Noch keine Arbeitsfassung formuliert. Quellen und Gespräche können bereits Grundlagen enthalten.')}</div></section>
 ${topic.proposals.length?`<section class="section"><h2>Frühere Änderungsvorschläge</h2>${topic.proposals.map(p=>`<article class="entry"><p class="eyebrow">${esc(p.status)}</p><p class="small">${esc(p.reason)}</p><details><summary>Vorschlag mit aktueller Fassung vergleichen</summary><div class="compare"><div class="prose">${esc(topic.content)}</div><div class="prose">${esc(p.content)}</div></div></details>${p.status==='Offen'?`<div class="actions"><button data-old-proposal="${p.id}" data-proposal-action="accept" ${topic.locked?'disabled':''}>Als Arbeitsfassung annehmen</button><button data-old-proposal="${p.id}" data-proposal-action="reject">Ablehnen</button></div>`:''}</article>`).join('')}</section>`:''}<section class="section"><h2>Varianten</h2><p class="small">Alternativen bleiben sichtbar, bis ihr bewusst eine Richtung wählt.</p>${topic.variants.length?topic.variants.map(v=>`<article class="entry"><h3>${esc(v.title)}</h3><div class="prose">${esc(v.content)}</div><button data-workshop="${esc(v.session_id)}">In der Werkstatt weiterdenken</button></article>`).join(''):'<p class="muted">Noch keine Varianten festgehalten.</p>'}</section></section>
 <aside class="topic-secondary">${impactSection(topic.id)}<section class="section"><h2>Offene Fragen${topic.questions.some(q=>q.inherited&&isOpen(q))?' inkl. Unterthemen':''}</h2>${topic.questions.filter(q=>isOpen(q)).map(questionRow).join('')||'<p class="muted">Noch keine offenen Fragen festgehalten. Das ist kein Nachweis für ein vollständiges Konzept.</p>'}<button id="new-question">Frage festhalten</button></section>
 <section class="section"><h2>Werkstätten</h2>${topic.sessions.map(s=>`<button class="list-row" data-workshop="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${stamp(s.at)} · ${s.summary?esc(s.summary.slice(0,180)):'Gedanken entwickeln und später wieder aufnehmen'}</small></button>`).join('')||'<p class="muted">Beginne mit einer Idee. Ein festes Arbeitsziel ist nicht nötig.</p>'}</section>
 <section class="section"><h2>Aktuelle Quellen (${activeSources.length})</h2>${activeSources.map(s=>`<button class="list-row" data-source="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc(s.coverage)}</small></button>`).join('')||'<p class="muted">Noch keine aktuelle Quelle zugeordnet.</p>'}${archivedSources.length?`<details><summary>Archiv & abgelöste Fassungen (${archivedSources.length})</summary>${archivedSources.map(s=>`<button class="list-row" data-source="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc(s.policy.status)}</small></button>`).join('')}</details>`:''}</section>
 <section class="section"><h2>Verbundene Themen</h2>${G.edges.filter(e=>e.a===topic.id||e.b===topic.id).map(e=>{const id=e.a===topic.id?e.b:e.a;return `<button class="list-row" data-topic="${esc(id)}"><strong>${esc(title(id))}</strong><small>${esc(e.label)}</small></button>`}).join('')||'<p class="muted">Noch keine zusätzlichen Beziehungen erfasst.</p>'}<button id="versions">Frühere Arbeitsfassungen (${topic.revisions.length})</button></section></aside></div>`}
async function clarify(qid){const s=await api('work-questions/'+qid+'/explore',{});$('#modal').close();go('workshop',s.id)}
async function begin(nid){const sessions=await api('workbench/'+nid);if(sessions.sessions.length){go('workshop',sessions.sessions[0].id);return}await createExploration(nid)}
async function createExploration(nid,name=''){const s=await api('explorations',{node_id:nid,title:name});go('workshop',s.id)}
function draftKey(){return 'mandraya-chat:'+$('#user').textContent+':'+exploration.id}
function recordCards(records){return (records||[]).map(r=>{recordCache.set(r.id,r);return `<article class="record-card"><h3>${esc({statement:'Aussage zum Beschließen',question:'Offene Frage',variant:'Variante',working:'Arbeitsfassung',resolution:'Frage klären · Ergebnis prüfen'}[r.kind])}</h3><p class="small">${esc(title(r.node_id))} · ${esc(r.status)}</p><div class="prose">${esc(r.content)}</div><button data-record="${r.id}" ${r.status!=='Entwurf'?'disabled':''}>Prüfen & festhalten</button></article>`}).join('')}
function groundingInfo(g){if(!g)return '<p class="small">Für diese ältere Antwort ist kein Projektstand-Beleg gespeichert. Vor Entscheidungen neu prüfen lassen.</p>';const r=JSON.parse(g.receipt);return `<details class="evidence"><summary>${g.stale?'Projektstand inzwischen geändert':'Grundlage dieser Antwort'} · ${stamp(g.at)}</summary>${g.stale?'<p class="notice">Diese Antwort bezieht sich auf einen früheren Projektstand. Für weitere Entscheidungen bitte die KI neu prüfen lassen.</p>':''}<p>Bereitgestellte Themenstände:</p>${(r.consulted_nodes||[r.selected_node]).map(n=>`<button class="list-row" data-topic="${esc(n.id)}">${esc(n.title)} · Arbeitsfassung ${n.version}</button>`).join('')}<p class="small">${esc(r.coverage)}</p><p class="small">Aktuell bedeutet der gespeicherte Stand im Assistenten. Änderungen an Originaldateien werden erst nach ihrem Import berücksichtigt.</p></details>`}
function chatEntry(h){return `<article class="chat-message"><p class="eyebrow">${h.role==='user'?esc(h.actor):'Mandraya Assistant'} · ${stamp(h.at)}${h.status!=='completed'?' · Unvollständig':''}</p><div class="rich">${rich(h.content||'Die Antwort wurde nicht abgeschlossen.')}</div>${h.role==='assistant'&&h.status==='completed'?groundingInfo(h.grounding)+sourceLinks(h.evidence)+recordCards(h.records):''}</article>`}
async function renderWorkshop(){header(topicCrumb()+`<button class="text-button" data-topic="${esc(topic.id)}"> / ${esc(topic.title)}</button>`,topic.title,'Werkstatt · Ideen untersuchen, Varianten behalten, Ergebnisse bewusst übernehmen.',`<button id="chat-history-open">Verlauf öffnen</button><button id="review" class="primary" ${chatBusy?'disabled':''}>Zwischenstand prüfen</button>`);$('#main').classList.add('workshop');const chats=history.filter(h=>(h.kind||'chat')==='chat');const lastUser=chats.findLastIndex(h=>h.role==='user');const recent=exploration.question?chats:(lastUser>=0?chats.slice(lastUser):[]);$('#main').classList.toggle('question-workshop',!!exploration.question);
 $('#scene').innerHTML=`<div class="workshop-grid"><section class="work-area"><div class="work-heading"><div><h2>${esc(exploration.title)}</h2></div><button id="new-exploration">Neue Diskussion</button></div>${exploration.impact&&!exploration.question?`<section class="section"><h3>Diesen Prüfhinweis besprechen wir</h3><p class="prose">${esc(exploration.impact.question)}</p><p>${esc(exploration.impact.reason)}</p>${exploration.impact.stale?'<p class="notice">Der Hinweis stammt aus einer früheren Grundlage. Die KI muss seine Annahmen am aktuellen Projektstand prüfen.</p>':''}<button data-prompt="${esc('Untersuche diesen Prüfhinweis anhand des aktuellen Projektstands: '+exploration.impact.question+' Prüfe zuerst, ob die Diskrepanz tatsächlich besteht, und beachte die Auswirkungen auf andere Bereiche.')}">Hinweis gemeinsam prüfen</button><p class="small">Die Diskussion speichert noch keine offene Frage und beschließt nichts.</p></section>`:''}${exploration.question?`<section class="question-focus"><h2>${esc(exploration.question.question)}</h2><details><summary>Hintergrund · ${esc(exploration.question.status)}</summary><p>${esc(exploration.question.reason)}</p>${exploration.question.answer?`<p class="prose">Bisheriges Ergebnis: ${esc(exploration.question.answer)}</p>`:''}</details>${!isOpen(exploration.question)?'<p class="small">Diese Frage ist geklärt oder archiviert. Das Gespräch bleibt erhalten.</p>':''}</section>`:''}${exploration.summary?`<details class="resume"><summary>Hier könnt ihr wieder ansetzen</summary>${exploration.stale?'<p class="notice">Die Projektgrundlage hat sich seit diesem Zwischenstand geändert. Die KI muss den aktuellen Stand neu berücksichtigen.</p>':''}<div class="prose">${esc(exploration.summary)}</div></details>`:''}<div id="latest-exchange">${recent.length?recent.map(chatEntry).join(''):exploration.question?`<div class="work-empty"><p>Besprich diese Frage mit der KI. Du kannst Möglichkeiten abwägen und später ein Ergebnis zur Prüfung vorbereiten lassen.</p><button data-prompt="${esc('Untersuche diese offene Frage anhand des aktuellen Projektstands und der relevanten Quellen: '+exploration.question.question+' Zeige Möglichkeiten, Abhängigkeiten und offene Annahmen. Noch nichts übernehmen.')}">Klärung beginnen</button></div>`:'<div class="work-empty"><h2>Was möchtest du weiterdenken?</h2><p>Beginne mit einer Idee oder einer Frage. Die KI berücksichtigt das Gesamtprojekt und weist auf konkrete Auswirkungen und Konflikte hin.</p><button data-prompt="Fasse den aktuellen Stand dieses Themas zusammen. Unterscheide Beschlüsse, Arbeitsfassung, Varianten und offene Fragen.">Stand gemeinsam verstehen</button></div>'}</div>
 <div class="composer">${!chatState.plan_enabled?'<p class="notice">Verbinde zuerst dein eigenes ChatGPT-Konto. <button data-view="ai">Verbindung ansehen</button></p>':''}<label for="chat-input">Deine Frage oder Idee</label><textarea id="chat-input" placeholder="Lass uns einen Gedanken ausprobieren …" ${chatBusy||!chatState.plan_enabled?'disabled':''}>${esc(localStorage.getItem(draftKey())||'')}</textarea><div class="composer-actions"><div><label for="chat-model">Modell</label><select id="chat-model" disabled><option>${chatState.plan_enabled?'Modelle werden geladen …':'ChatGPT noch nicht verbunden'}</option></select></div><div class="actions"><button id="chat-stop" ${chatBusy?'':'hidden'}>Antwort stoppen</button><button id="chat-send" class="primary" disabled>Mit der KI weiterdenken</button></div></div><p id="chat-status" role="status" aria-live="polite" class="small">Du kannst sagen: „Bereite daraus eine Aussage oder offene Frage vor.“ Die KI zeigt einen vorausgefüllten Entwurf zur Bestätigung. Relevante Projekttexte gehen an OpenAI.</p></div></section>
 <aside class="work-context" id="work-context">${impactSection(topic.id)}<h2>Grundlage & Auswirkungen</h2><p class="small">${esc(topic.scope)} · Arbeitsfassung ${topic.version}</p><button data-topic="${esc(topic.id)}">Themenstand ansehen</button><h3>Gesetzte Aussagen</h3>${topic.statements.filter(s=>s.status==='Beschlossen').map(s=>`<div class="entry prose">${esc(s.content)}</div>`).join('')||'<p class="muted">Keine einzelnen Aussagen beschlossen.</p>'}${topic.locked?'<p class="notice">Die bisherige Gesamtfassung ist geschützt.</p>':''}<h3>Fragen zu diesem Thema${topic.questions.some(q=>q.inherited&&isOpen(q))?' & Unterthemen':''}</h3>${topic.questions.filter(q=>isOpen(q)).map(questionRow).join('')||'<p class="muted">Noch keine Fragen festgehalten.</p>'}<button id="new-question">Frage oder Auswirkung festhalten</button><h3>Im ganzen Projekt</h3><p>${questions.filter(q=>isOpen(q)).length} offene oder zurückgestellte Fragen.</p><button data-view="questions">Alle offenen Fragen</button><p class="small">Die KI prüft neue Unklarheiten im Gespräch und bereitet konkrete Fragen beim passenden Thema zur Bestätigung vor. Fragen in Unterthemen sind auch hier sichtbar.</p>${exploration.review&&!exploration.review.applied?'<button id="pending-review">Letzten Zwischenstand prüfen</button>':''}</aside></div>`;
 if(exploration.question){$('#viewtitle').textContent='Frage klären';$('#viewsubtitle').textContent=topic.title;$('#viewactions').innerHTML=`<button data-topic="${esc(topic.id)}">Zum Thema</button><button id="question-context-toggle" aria-expanded="false" aria-controls="work-context">Projektkontext</button><button id="chat-history-open">Älteren Verlauf öffnen</button><button id="review" hidden></button>`;$('#work-context').hidden=true;$('#new-exploration').hidden=true;$('.work-heading').hidden=true;$('#chat-input').placeholder='Deine Gedanken oder Rückfragen …';$('#chat-send').textContent='Senden';const transcript=$('#latest-exchange');transcript.setAttribute('role','region');transcript.setAttribute('aria-label','Gespräch zur Frage');transcript.scrollTop=transcript.scrollHeight;}
 $('#chat-input').oninput=()=>localStorage.setItem(draftKey(),$('#chat-input').value);
 if(chatState.plan_enabled){try{models=await api('chatgpt/models');if(current.page!=='workshop'||current.id!==exploration.id)return;const previous=localStorage.getItem('mandraya-model');$('#chat-model').innerHTML=models.length?models.map(m=>`<option value="${esc(m.slug)}" ${m.slug===previous?'selected':''}>${esc(m.display_name)}</option>`).join(''):'<option>Keine Modelle freigegeben</option>';$('#chat-model').disabled=!models.length||chatBusy;$('#chat-send').disabled=!models.length||chatBusy;$('#review').disabled=!models.length||chatBusy||!chats.some(h=>h.role==='assistant'&&h.status==='completed');$('#chat-model').onchange=()=>localStorage.setItem('mandraya-model',$('#chat-model').value)}catch(e){$('#chat-status').textContent=e.message;$('#review').disabled=true}}
 else $('#review').disabled=true;
}
function modal(name,html){$('#modal-title').textContent=name;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function sourceModal(name,html){$('#source-modal-title').textContent=name;$('#source-modal-body').innerHTML=html;if(!$('#source-modal').open)$('#source-modal').showModal()}
async function sourceDetail(id,version){const s=await api('sources/'+encodeURIComponent(id)),v=version?s.versions.find(v=>String(v.id)===String(version)):s.versions[0];if(!v)throw Error('Quellenfassung nicht gefunden.');sourceModal(s.title,`${s.policy&&s.policy.status!=='Aktuell'?`<p class="notice">${esc(s.policy.status)}: ${esc(s.policy.reason)}${s.policy.successor_id?` <button data-source="${esc(s.policy.successor_id)}">Aktuelle Dokumentfassung öffnen</button>`:''}</p>`:''}<p class="eyebrow">${version?'Zitierte':'Neueste'} Quellenfassung ${v.id} · ${stamp(v.at)}</p><p class="small">${esc(s.coverage)} · ${esc(s.path)}</p><div class="prose source-content">${esc(v.content||'Nur Metadaten erfasst. Kein lesbarer Text gespeichert.')}</div>${v.id!==s.versions[0].id?`<details><summary>Mit neuester Fassung ${s.versions[0].id} vergleichen</summary><div class="compare"><div><h3>Gewählte Fassung ${v.id}</h3><div class="prose">${esc(v.content)}</div></div><div><h3>Neueste Fassung ${s.versions[0].id}</h3><div class="prose">${esc(s.versions[0].content)}</div></div></div></details>`:''}${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">Original öffnen</a>`:''}${s.versions.length>1?`<details><summary>Andere Fassungen ansehen</summary>${s.versions.map(x=>`<button class="list-row" data-source="${esc(id)}" data-version="${x.id}">Fassung ${x.id} · ${stamp(x.at)}</button>`).join('')}</details>`:''}`)}
async function streamRequest(mode){if(chatBusy)return;const nid=topic.id,sid=current.page==='workshop'?exploration.id:null;const input=mode==='chat'?$('#chat-input').value.trim():'Bitte den Arbeitsstand prüfen.';if(!input)throw Error('Bitte einen Gedanken oder eine Frage eingeben.');const model=current.page==='workshop'?$('#chat-model').value:await defaultModel();chatBusy=true;aborter=new AbortController();let completed=false;const output=mode==='chat'?document.createElement('article'):null;let text='';let followAnswer=true;const transcript=mode==='chat'?$('#latest-exchange'):null;const trackScroll=()=>{followAnswer=transcript.scrollHeight-transcript.scrollTop-transcript.clientHeight<80};if(transcript&&exploration.question)transcript.addEventListener('scroll',trackScroll);
 if(output){output.className='chat-message';output.innerHTML='<p class="eyebrow">Mandraya Assistant · Antwort entsteht</p><div class="prose"></div>';if(!exploration.question)$('#latest-exchange').innerHTML='';else $('#latest-exchange').querySelector('.work-empty')?.remove();$('#latest-exchange').insertAdjacentHTML('beforeend',chatEntry({role:'user',actor:$('#user').textContent,at:new Date().toISOString(),content:input,status:'completed'}));$('#latest-exchange').append(output);if(exploration.question)$('#latest-exchange').scrollTop=$('#latest-exchange').scrollHeight;$('#chat-send').disabled=true;$('#review').disabled=true;$('#chat-input').disabled=true;$('#chat-stop').hidden=false}
 if(mode==='review')modal('Zwischenstand wird vorbereitet', '<p>Die KI ordnet eure Diskussion, Varianten und konkreten Auswirkungen. Anschließend prüfst du den Entwurf.</p><p id="review-progress" role="status">Projektgrundlage wird geprüft …</p>');
 const update=t=>{const el=mode==='brief'?$('#brief-status'):mode==='review'?$('#review-progress'):$('#chat-status');if(el)el.textContent=t};update('Projektgrundlage wird geprüft …');
 try{const r=await fetch('/api/chat/'+nid,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:input,model,session_id:sid,mode}),signal:aborter.signal});if(!r.ok){const p=await r.json();throw Error(p.detail||'Anfrage fehlgeschlagen.')}const reader=r.body.getReader(),decoder=new TextDecoder();let pending='';const consume=line=>{if(!line.trim())return;const e=JSON.parse(line);if(e.type==='delta'){text+=e.text;if(output){output.querySelector('.prose').textContent=text;if(exploration.question&&followAnswer)transcript.scrollTop=transcript.scrollHeight}}if(e.type==='activity')update(e.text);if(e.type==='error')throw Error(e.message);if(e.type==='done')completed=true};while(true){const {done,value}=await reader.read();pending+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=pending.split('\n');pending=lines.pop();lines.forEach(consume);if(done){consume(pending);break}}if(!completed)throw Error('Die Antwort wurde nicht vollständig abgeschlossen.');if(mode==='chat')localStorage.removeItem(draftKey())}
 catch(e){toast(e.name==='AbortError'?'Antwort gestoppt. Zwischenstände bleiben erhalten.':e.message);if(mode==='review')$('#modal-body').innerHTML='<p>Der Zwischenstand konnte nicht erstellt werden. Eure Diskussion bleibt erhalten.</p>'}
 finally{if(transcript)transcript.removeEventListener('scroll',trackScroll);chatBusy=false;aborter=null;if(current.id===(sid||nid)){if(mode==='chat'&&exploration.question){const scroll=transcript.scrollTop;[history,exploration,topic]=await Promise.all([api('chat/'+nid+'?session_id='+sid),api('explorations/'+sid),api('workbench/'+nid)]);const chats=history.filter(h=>(h.kind||'chat')==='chat');transcript.innerHTML=chats.map(chatEntry).join('');transcript.scrollTop=followAnswer?transcript.scrollHeight:scroll;$('#chat-input').disabled=false;$('#chat-input').value=localStorage.getItem(draftKey())||'';$('#chat-send').disabled=false;$('#chat-model').disabled=false;$('#chat-stop').hidden=true;$('#chat-status').textContent=completed?'Antwort gespeichert. Du kannst weiterfragen oder sagen: „Bereite das Ergebnis zur Übernahme vor.“':'Die Antwort wurde unterbrochen. Du kannst es erneut versuchen.';}else await route(true);if(mode==='review'&&completed)showReview();if(mode==='chat'&&completed)toast('Antwort gespeichert. Du kannst weiterdenken oder den Zwischenstand prüfen.')}}
}
async function defaultModel(){const s=await api('chatgpt/status');if(!s.plan_enabled)throw Error('Bitte zuerst dein ChatGPT-Konto verbinden.');const m=await api('chatgpt/models');if(!m.length)throw Error('Keine Modelle freigegeben.');return m.find(x=>x.slug===localStorage.getItem('mandraya-model'))?.slug||m[0].slug}
function showReview(){const rev=exploration.review;if(!rev)throw Error('Noch kein Zwischenstand vorhanden.');const r=rev.content;const saved=JSON.parse(localStorage.getItem('mandraya-review:'+$('#user').textContent+':'+rev.id)||'null');
 modal('Zwischenstand prüfen',`<p>Bearbeite den Entwurf. Nur ausdrücklich ausgewählte Inhalte werden ins Projekt übernommen. Der Gesprächsstand bleibt als Einstieg für später erhalten.</p>${rev.stale?'<p class="notice">Die Projektgrundlage hat sich geändert. Bitte diesen Zwischenstand neu erstellen.</p>':''}${rev.applied?'<p class="notice">Dieser Zwischenstand wurde bereits übernommen.</p>':''}${sourceLinks(rev.evidence)}<form id="review-form"><label for="review-summary">Was haben wir herausgearbeitet?</label><textarea id="review-summary">${esc(r.summary)}</textarea><label for="review-next">Wo können wir weiterarbeiten?</label><textarea id="review-next" class="short-text">${esc(r.next_steps)}</textarea><section class="section"><h3>Arbeitsfassung</h3><label class="check"><input type="checkbox" id="take-draft" ${!r.draft||topic.locked?'disabled':''}> Geänderte Arbeitsfassung übernehmen</label>${topic.locked?'<p class="small">Die bisherige Gesamtfassung muss vorher wieder geöffnet werden.</p>':''}<textarea id="review-draft">${esc(r.draft)}</textarea><details><summary>Aktuelle Fassung zum Vergleich</summary><div class="prose">${esc(topic.content||'Noch leer')}</div></details></section>
 <section class="section"><h3>Varianten erhalten</h3>${r.variants.map((v,i)=>`<div class="review-item" data-variant-index="${i}"><label class="check"><input type="checkbox" class="take"> Diese Variante festhalten</label><label>Titel<input class="variant-title" value="${esc(v.title)}"></label><label>Beschreibung<textarea class="variant-content short-text">${esc(v.content)}</textarea></label></div>`).join('')||'<p class="muted">Keine zusätzlichen Varianten vorgeschlagen.</p>'}</section>
 <section class="section"><h3>Präzise Aussagen beschließen</h3><p class="small">Diese Aussagen werden nach deiner Bestätigung geschützt. Der übrige Themenstand bleibt bearbeitbar.</p>${r.statements.map((s,i)=>`<div class="review-item" data-statement-index="${i}"><label class="check"><input type="checkbox" class="take"> Diese konkrete Aussage beschließen</label><textarea class="statement-content short-text">${esc(s)}</textarea></div>`).join('')||'<p class="muted">Keine Beschlussaussagen vorgeschlagen.</p>'}</section>
 <section class="section"><h3>Fragen und Auswirkungen festhalten</h3>${r.questions.map((q,i)=>`<div class="review-item" data-question-index="${i}"><label class="check"><input type="checkbox" class="take"> Als offene Frage übernehmen</label><label>Betroffenes Thema<select class="question-node">${nodeOptions(q.node_id)}</select></label><label>Frage<textarea class="question-content short-text">${esc(q.question)}</textarea></label><label>Warum betrifft das dieses Thema?<textarea class="question-reason short-text">${esc(q.reason)}</textarea></label></div>`).join('')||'<p class="muted">Keine konkreten offenen Fragen vorgeschlagen.</p>'}</section><label for="review-reason">Begründung deiner Übernahme</label><input id="review-reason" placeholder="Was hast du geprüft und warum übernimmst du es?"><div class="actions"><button type="button" id="apply-review" class="primary" ${rev.stale||rev.applied?'disabled':''}>Auswahl übernehmen & Zwischenstand merken</button><button type="button" id="modal-close-secondary">Später prüfen</button></div><p class="small">Ohne Auswahl wird nur der bearbeitete Gesprächsstand gespeichert. Nichts wird automatisch beschlossen. Deine Bearbeitung wird bis dahin auf diesem Gerät zwischengespeichert.</p></form>`);
 const fields=[...$('#review-form').querySelectorAll('input,textarea,select')];if(saved)fields.forEach((f,i)=>{if(saved[i]!==undefined){if(f.type==='checkbox')f.checked=saved[i];else f.value=saved[i]}});$('#review-form').oninput=()=>localStorage.setItem('mandraya-review:'+$('#user').textContent+':'+rev.id,JSON.stringify(fields.map(f=>f.type==='checkbox'?f.checked:f.value)));$('#review-form').onsubmit=e=>e.preventDefault();
}
const nodeOptions=id=>G.nodes.map(n=>`<option value="${esc(n.id)}" ${n.id===id?'selected':''}>${esc(n.scope+' · '+n.title)}</option>`).join('');
async function applyReview(){const variants=[...$('#review-form').querySelectorAll('[data-variant-index]')].filter(e=>e.querySelector('.take').checked).map(e=>({title:e.querySelector('.variant-title').value,content:e.querySelector('.variant-content').value})),statements=[...$('#review-form').querySelectorAll('[data-statement-index]')].filter(e=>e.querySelector('.take').checked).map(e=>e.querySelector('.statement-content').value),qs=[...$('#review-form').querySelectorAll('[data-question-index]')].filter(e=>e.querySelector('.take').checked).map(e=>({node_id:e.querySelector('.question-node').value,question:e.querySelector('.question-content').value,reason:e.querySelector('.question-reason').value}));await api('work-reviews/'+exploration.review.id+'/apply',{summary:$('#review-summary').value,next_steps:$('#review-next').value,draft:$('#take-draft').checked?$('#review-draft').value:null,variants,statements,questions:qs,reason:$('#review-reason').value});$('#modal').close();await route();toast('Ausgewählte Ergebnisse übernommen. Du kannst später hier weiterarbeiten.')}
function editConcept(){modal('Gemeinsame Arbeitsfassung',`<p class="small">Fassung ${topic.version} · Änderungen bleiben nachvollziehbar. Einzelne Beschlüsse werden separat verwaltet.</p>${topic.locked?'<p class="notice">Diese bisherige Gesamtfassung ist geschützt. Zum Bearbeiten ausdrücklich wieder öffnen.</p>':''}<label for="concept-text">Arbeitsfassung</label><textarea id="concept-text" ${topic.locked?'readonly':''}>${esc(topic.content)}</textarea><label for="concept-stage">Entwicklungsstand</label><select id="concept-stage">${['Ungeprüft','In Bearbeitung','Klärung nötig','Ausgearbeitet'].map(s=>`<option ${topic.stage===s?'selected':''}>${s}</option>`).join('')}</select><label for="concept-reason">Begründung</label><input id="concept-reason"><button id="save-concept" class="primary">${topic.locked?'Gesamtfassung wieder öffnen':'Arbeitsfassung speichern'}</button>`)}
async function utility(kind){if(kind==='impact'){header('PROJEKTWEIT','Automatische Projektprüfung','Neue Dokumente und übernommene Änderungen lösen eine Prüfung ihrer Auswirkungen aus.','<button data-impact-check="mandraya">Jetzt zusätzlich prüfen</button>');$('#scene').innerHTML=`<div class="utility"><p>Die KI prüft Anlass und mögliche Auswirkungen im ganzen Projekt. Hinweise werden erst durch deine Bestätigung zu offenen Fragen. Die Prüfung nutzt das ChatGPT-Konto der auslösenden Person.</p>${impactData.service_error?`<p class="notice">${esc(impactData.service_error)}</p>`:''}${impactData.pending?`<p class="notice">${impactData.pending} Prüfauftrag bzw. Prüfaufträge laufen, warten oder benötigen eine Verbindung.</p>`:''}<h2>Hinweise zur Prüfung</h2>${(impactData.reconciliations||[]).map(reconcileRow).join('')}${impactData.findings.map(findingRow).join('')||((impactData.reconciliations||[]).length?'':'<p class="muted">Keine offenen Prüfhinweise. Das bedeutet nicht, dass das Konzept vollständig oder widerspruchsfrei ist.</p>')}<h2>Letzte Prüfaufträge</h2>${impactData.jobs.map(j=>`<article class="entry"><h3>${esc(j.state)}</h3><p class="small">${stamp(j.updated)}</p>${j.error?`<p class="notice">${esc(j.error)}</p>`:''}${j.result?`<p>${esc(JSON.parse(j.result).summary)}</p>`:''}<p class="small">Auslöser: ${esc(JSON.parse(j.events).map(e=>({'save':'Arbeitsfassung gespeichert','lock':'Gesamtfassung geschützt','unlock':'Gesamtfassung wieder geöffnet'}[e.action]||e.action)+' · '+(e.kind==='node'?title(e.id):e.kind==='source'?'Dokument':'Projekt')).join(', '))}</p>${j.state==='Fehlgeschlagen'||j.state==='Verbindung nötig'?'<button data-impact-check="mandraya">Mit meinem Konto erneut prüfen</button>':''}</article>`).join('')||'<p class="muted">Noch kein Prüfauftrag. Der nächste gespeicherte Input oder Konzeptwechsel löst die Prüfung automatisch aus.</p>'}<p class="small">${esc(impactData.coverage)}</p></div>`}
 else if(kind==='questions'){header('PROJEKTWEIT','Offene Fragen','Konkrete Auswirkungen behalten ihren Ursprung. Zurückstellen bedeutet nicht verlieren.');$('#scene').innerHTML=`<div class="utility"><div class="tabs"><button data-question-filter="active" class="active">Offen & zurückgestellt</button><button data-question-filter="all">Alle einschließlich geklärter & archivierter Fragen</button></div><div id="question-list">${questions.filter(q=>isOpen(q)).map(questionRow).join('')||'<p class="muted">Noch keine offenen Fragen festgehalten.</p>'}</div></div>`}
 else if(kind==='sources'){header('GRUNDLAGEN','Quellensammlung','Archivierte Fassungen ansehen und mit dem Original vergleichen.');const rows=await api('sources');$('#scene').innerHTML=`<div class="utility"><label for="source-search">Quellen suchen</label><input id="source-search" placeholder="Titel oder Ordner"><div id="source-list">${rows.map(s=>`<button class="list-row" data-source="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc(s.path)} · ${s.versions} Fassungen · ${esc(s.coverage)}</small></button>`).join('')}</div></div>`;$('#source-search').oninput=e=>$('#source-list').querySelectorAll('button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
 else if(kind==='input'){header('GRUNDLAGEN','Neuer Input','Ideen und Dateien archivieren. Sie ändern keinen Beschluss.');$('#scene').innerHTML=`<div class="utility"><label for="input-title">Titel</label><input id="input-title"><label for="input-content">Idee oder Quellentext</label><textarea id="input-content"></textarea><label for="input-node">Thema zuordnen</label><select id="input-node"><option value="">Noch nicht zuordnen</option>${nodeOptions('')}</select><button id="submit-input" class="primary">Text archivieren</button><hr><label for="upload">Datei archivieren (maximal 16 MB)</label><input id="upload" type="file"></div>`;$('#upload').onchange=()=>safely(async()=>{const file=$('#upload').files[0];if(!file)return;const f=new FormData();f.append('file',file);f.append('node',$('#input-node').value);const r=await fetch('/api/upload',{method:'POST',body:f}),p=await r.json();if(!r.ok)throw Error(p.detail);toast('Datei archiviert.');go('sources')})}
 else if(kind==='audit'){header('NACHVOLLZIEHBARKEIT','Änderungsverlauf','Wer hat was geändert — und auf welcher Grundlage?');const rows=await api('audit');$('#scene').innerHTML=`<div class="utility">${rows.map(r=>`<details class="entry"><summary>${esc(r.action)}</summary><p class="small">${esc(r.actor)} · ${stamp(r.at)}</p><h3>Vorher</h3><pre class="prose">${esc(r.before_json)}</pre><h3>Nachher</h3><pre class="prose">${esc(r.after_json)}</pre></details>`).join('')||'<p>Noch keine Änderungen.</p>'}</div>`}
 else if(kind==='ai'){header('PERSÖNLICHER ZUGANG','ChatGPT-Verbindung','Gemeinsames Projektwissen · getrennte Konten');const s=await api('chatgpt/status');$('#scene').innerHTML=`<div class="utility"><h2>${s.connected?'Konto verbunden':'ChatGPT-Abo verbinden'}</h2>${s.connected?`<p>${esc(s.account)}</p><p>${s.plan_enabled?'Abo-Nutzung freigegeben. Öffne ein Thema und seine Werkstatt.':'Abo-Nutzung noch nicht freigegeben. Bitte erneut verbinden.'}</p><button id="disconnect">Verbindung trennen</button>`:'<p>Die persönliche Anmeldung erfolgt über den Anmeldehelfer auf deinem Computer. Codex kann dich bei der Einrichtung begleiten.</p>'}<p>Jede Person verwendet ihre eigene ChatGPT-Verbindung. Projektstand und Diskussionen teilt ihr weiterhin.</p><p class="small">Keine bisherigen ChatGPT-Gespräche werden übernommen. Keine automatische kostenpflichtige API-Abrechnung.</p><a href="https://chatgpt.com/#settings" target="_blank" rel="noopener">ChatGPT-Einstellungen öffnen</a></div>`}
 else go('dashboard','mandraya')}
function showQuestion(id){const q=questions.find(q=>q.id===id)||topic.questions.find(q=>q.id===id);modal('Offene Frage',`<h3>${esc(q.question)}</h3><p class="small">${esc(q.status)} · ${esc(title(q.node_id))}</p><p>${esc(q.reason)}</p><p class="small">Entstanden bei ${esc(title(q.origin_node))}. Die Klärung hier beschließt noch keine Konzeptaussage.</p><label for="q-answer">Ergebnis der Klärung</label><textarea id="q-answer" class="short-text">${esc(q.answer)}</textarea><label for="q-reason">Begründung</label><input id="q-reason"><div class="actions"><button data-q-action="resolve" data-q-id="${q.id}" data-q-version="${q.version}" class="primary">Als geklärt festhalten</button><button data-q-action="defer" data-q-id="${q.id}" data-q-version="${q.version}">Zurückstellen</button>${q.status!=='Offen'?`<button data-q-action="reopen" data-q-id="${q.id}" data-q-version="${q.version}">Wieder öffnen</button>`:''}${isOpen(q)?`<button data-clarify="${esc(q.id)}">Mit KI klären</button>`:''}</div>`)}
function showStatement(id){const s=topic.statements.find(s=>s.id===id);modal('Präzise Aussage',`<p class="eyebrow">${esc(s.status)} · Fassung ${s.version}</p><label for="statement-text">Aussage</label><textarea id="statement-text" class="short-text" ${s.status==='Beschlossen'?'readonly':''}>${esc(s.content)}</textarea><label for="statement-reason">Begründung</label><input id="statement-reason"><button id="change-statement" data-id="${s.id}" data-version="${s.version}" data-action="${s.status==='Beschlossen'?'reopen':'decide'}">${s.status==='Beschlossen'?'Beschluss ausdrücklich wieder öffnen':'Diese Aussage beschließen'}</button>`)}
document.addEventListener('click',e=>safely(async()=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.dashboard)go('dashboard',b.dataset.dashboard);if(b.dataset.topic)go('topic',b.dataset.topic);if(b.dataset.workshop)go('workshop',b.dataset.workshop);if(b.dataset.view)go(b.dataset.view);if(b.dataset.begin){$('#modal').close();await begin(b.dataset.begin)}
 if(b.dataset.reconcile)showReconciliation(b.dataset.reconcile);
 if(b.dataset.reconcileApply){const batch=(impactData.reconciliations||[]).find(x=>x.id===b.dataset.reconcileApply);const chosen=[...$('#reconcile-form').querySelectorAll('[data-reconcile-item]')].filter(e=>e.querySelector('.take').checked).map(e=>{const i=batch.items.find(i=>i.id===e.dataset.reconcileItem);return {id:i.id,after:i.kind==='working'?{content:e.querySelector('.reconcile-content').value}:{question:e.querySelector('.reconcile-question')?.value||i.after.question,answer:e.querySelector('.reconcile-answer').value}}});await api('reconcile/'+batch.id,{action:'apply',items:chosen,reason:$('#reconcile-reason').value});$('#modal').close();await route();toast('Ausgewählte Änderungen übernommen. Frühere Stände bleiben erhalten.')}
 if(b.dataset.reconcileReject){await api('reconcile/'+b.dataset.reconcileReject,{action:'reject'});$('#modal').close();await route();toast('Abgleich verworfen. Der Projektstand bleibt erhalten.')}
 if(b.dataset.impactCheck){await api('impact/check',{node_id:b.dataset.impactCheck});toast('Prüfauftrag gespeichert. Die KI prüft im Hintergrund.');await route()}
 if(b.dataset.impactDiscuss){const r=await api('impact/findings/'+b.dataset.impactDiscuss,{action:'discuss'});go('workshop',r.session_id)}
 if(b.dataset.impactReview){const f=impactData.findings.find(f=>f.id===b.dataset.impactReview);modal('Prüfhinweis als offene Frage',`<p>Prüfe die Zuordnung und den Anlass. Damit wird noch nichts beschlossen.</p><label for="impact-node">Betroffenes Thema</label><select id="impact-node">${nodeOptions(f.node_id)}</select><label for="impact-question">Offene Frage</label><textarea id="impact-question" class="short-text">${esc(f.question)}</textarea><label for="impact-reason">Begründung / Auswirkung</label><textarea id="impact-reason" class="short-text">${esc(f.reason)}</textarea>${findingEvidence(f)}<button data-impact-save="${f.id}" class="primary">Offene Frage festhalten</button>`)}
 if(b.dataset.impactSave){await api('impact/findings/'+b.dataset.impactSave,{action:'save',node_id:$('#impact-node').value,question:$('#impact-question').value,reason:$('#impact-reason').value});$('#modal').close();await route();toast('Offene Frage beim betroffenen Thema festgehalten.')}
 if(b.dataset.impactReject){await api('impact/findings/'+b.dataset.impactReject,{action:'reject'});await route();toast('Prüfhinweis verworfen.')}
 if(b.id==='question-context-toggle'){const panel=$('#work-context');panel.hidden=!panel.hidden;b.setAttribute('aria-expanded',String(!panel.hidden));b.textContent=panel.hidden?'Projektkontext':'Projektkontext schließen';}
 if(b.dataset.clarify)await clarify(b.dataset.clarify);
 if(b.dataset.record){const r=recordCache.get(b.dataset.record);modal('Entwurf aus dem Gespräch',`<p>${esc({statement:'Erst deine Bestätigung beschließt diese präzise Aussage.',question:'Die Frage wird beim betroffenen Thema und projektweit sichtbar.',variant:'Diese Variante bleibt als mögliche Richtung erhalten.',working:'Diese vollständige Fassung ersetzt die aktuelle Arbeitsfassung.',resolution:'Deine Bestätigung hält die Antwort fest und klärt diese Frage. Einen verbindlichen Beschluss wählst du ausdrücklich zusätzlich.'}[r.kind])}</p><label for="record-node">Thema</label><select id="record-node" ${r.kind==='resolution'?'disabled':''}>${nodeOptions(r.node_id)}</select>${r.kind==='resolution'?`<p class="prose">Frage: ${esc(questions.find(q=>q.id===r.question_id)?.question||r.question_id)}</p><label for="record-title">Möglicher Beschluss (optional)</label><textarea id="record-title" class="short-text">${esc(r.title)}</textarea><label class="check"><input type="checkbox" id="record-decide"> Diese präzise Aussage verbindlich beschließen</label><p class="small">Ohne Auswahl wird nur die Antwort gespeichert und die Frage geklärt. Bei Ablehnung bleibt sie offen.</p>`:''}${r.kind==='variant'?`<label for="record-title">Variantenname</label><input id="record-title" value="${esc(r.title)}">`:''}<label for="record-content">${r.kind==='question'?'Frage':r.kind==='resolution'?'Antwort / Ergebnis der Klärung':'Konkreter Inhalt'}</label><textarea id="record-content">${esc(r.content)}</textarea><label for="record-reason">Begründung</label><textarea id="record-reason" class="short-text">${esc(r.reason)}</textarea>${sourceLinks(r.evidence)}<div class="actions"><button data-record-confirm="${r.id}" class="primary">${esc({statement:'Diese Aussage beschließen',question:'Offene Frage festhalten',variant:'Variante festhalten',working:'Als Arbeitsfassung übernehmen',resolution:'Antwort übernehmen & Frage klären'}[r.kind])}</button><button data-record-reject="${r.id}">Entwurf verwerfen</button></div>`)}
 if(b.dataset.recordConfirm){const r=recordCache.get(b.dataset.recordConfirm);await api('chat-records/'+r.id,{action:'confirm',node_id:$('#record-node').value,content:$('#record-content').value,reason:$('#record-reason').value,title:$('#record-title')?.value??r.title,decide:$('#record-decide')?.checked||false});$('#modal').close();await route();toast('Geprüfter Entwurf festgehalten.')}if(b.dataset.recordReject){await api('chat-records/'+b.dataset.recordReject,{action:'reject'});$('#modal').close();await route()}
 if(b.dataset.source)await sourceDetail(b.dataset.source,b.dataset.version);if(b.dataset.question)showQuestion(b.dataset.question);if(b.dataset.statement)showStatement(b.dataset.statement);
 if(b.id==='source-modal-close')$('#source-modal').close();if(b.dataset.oldProposal){await api('proposals/'+b.dataset.oldProposal,{action:b.dataset.proposalAction});await route()}if(b.id==='modal-close'||b.id==='modal-close-secondary')$('#modal').close();if(b.id==='refresh')await route();if(b.id==='logout'){await api('logout',{});location.reload()}
 if(b.id==='chat-send')await streamRequest('chat');if(b.id==='chat-stop')aborter?.abort();if(b.id==='review')await streamRequest('review');if(b.id==='brief')await streamRequest('brief');if(b.id==='pending-review')showReview();if(b.id==='apply-review')await applyReview();
 if(b.id==='chat-history-open')modal('Gesprächsverlauf','<div id="older-history"></div><div>'+history.filter(h=>(h.kind||'chat')==='chat').map(chatEntry).join('')+'</div>'+(history.length===60?`<button id="older-chat" data-before="${history[0].sequence}">Älteren Verlauf laden</button>`:history.length?'':'<p>Noch keine Gespräche.</p>'));if(b.id==='older-chat'){const older=await api('chat/'+topic.id+'?session_id='+exploration.id+'&before='+b.dataset.before);$('#older-history').insertAdjacentHTML('afterbegin',older.filter(h=>(h.kind||'chat')==='chat').map(chatEntry).join(''));if(older.length===60)b.dataset.before=older[0].sequence;else b.remove()}
 if(b.id==='new-exploration')modal('Neue Diskussion beginnen','<p>Ein festes Ziel ist nicht nötig. Ein Name kann helfen, eure Gedanken später wiederzufinden.</p><label for="exploration-name">Name (optional)</label><input id="exploration-name" placeholder="Zum Beispiel: Verschiedene Lösungswege"><button id="create-exploration" class="primary">Werkstatt beginnen</button>');if(b.id==='create-exploration'){await createExploration(topic.id,$('#exploration-name').value);$('#modal').close()}if(b.dataset.prompt){$('#chat-input').value=b.dataset.prompt;$('#chat-input').dispatchEvent(new Event('input'));$('#chat-input').focus()}
 if(b.id==='edit-concept')editConcept();if(b.id==='save-concept'){await api('nodes/'+topic.id,{version:topic.version,action:topic.locked?'unlock':'save',content:$('#concept-text').value,stage:$('#concept-stage').value,reason:$('#concept-reason').value});$('#modal').close();await route();toast('Arbeitsfassung gespeichert.')}
 if(b.id==='versions')modal('Frühere Arbeitsfassungen',topic.revisions.map(r=>`<button class="list-row" data-revision="${r.id}"><strong>Fassung ${r.version}</strong><small>${esc(r.actor)} · ${stamp(r.at)} · ${esc(r.reason)}</small></button>`).join('')||'<p>Noch keine früheren Fassungen.</p>');
 if(b.dataset.revision){const r=await api('revisions/'+b.dataset.revision),old=JSON.parse(r.snapshot);modal('Fassung '+r.version,`<div class="compare"><div><h3>Früher</h3><div class="prose">${esc(old.content)}</div></div><div><h3>Aktuell</h3><div class="prose">${esc(topic.content)}</div></div></div><label for="restore-reason">Begründung der Wiederherstellung</label><input id="restore-reason"><button id="restore" ${topic.locked?'disabled':''}>Als neue Arbeitsfassung wiederherstellen</button>`);$('#restore').onclick=()=>safely(async()=>{await api('nodes/'+topic.id,{version:topic.version,action:'save',content:old.content,stage:old.stage,reason:$('#restore-reason').value});$('#modal').close();await route()})}
 if(b.dataset.questionFilter)$('#question-list').innerHTML=questions.filter(q=>b.dataset.questionFilter==='all'||isOpen(q)).map(questionRow).join('')||'<p>Keine Fragen in dieser Ansicht.</p>';
 if(b.dataset.qAction){await api('work-questions/'+b.dataset.qId,{version:Number(b.dataset.qVersion),action:b.dataset.qAction,reason:$('#q-reason').value,answer:$('#q-answer').value});$('#modal').close();await route()}
 if(b.id==='change-statement'){await api('statements/'+b.dataset.id,{version:Number(b.dataset.version),action:b.dataset.action,reason:$('#statement-reason').value,content:$('#statement-text').value});$('#modal').close();await route()}
 if(b.id==='new-question')modal('Frage oder Auswirkung festhalten',`<label for="new-q-node">Betroffenes Thema</label><select id="new-q-node">${nodeOptions(topic.id)}</select><label for="new-q-text">Welche Entscheidung oder Klärung fehlt?</label><textarea id="new-q-text" class="short-text"></textarea><label for="new-q-reason">Warum entsteht diese Frage hier?</label><input id="new-q-reason"><button id="save-question" class="primary">Frage festhalten</button>`);
 if(b.id==='save-question'){await api('work-questions',{node_id:$('#new-q-node').value,origin_node:topic.id,session_id:current.page==='workshop'?exploration.id:null,question:$('#new-q-text').value,reason:$('#new-q-reason').value});$('#modal').close();await route()}
 if(b.id==='new-statement')modal('Präzise Aussage beschließen',`<p>Formuliere nur das, was tatsächlich gesetzt sein soll. Andere Teile dieses Themas bleiben offen.</p><label for="new-statement-text">Konkrete Aussage</label><textarea id="new-statement-text" class="short-text"></textarea><label for="new-statement-reason">Warum beschließt du diese Aussage?</label><input id="new-statement-reason"><button id="save-statement" class="primary">Diese Aussage beschließen</button>`);
 if(b.id==='save-statement'){await api('statements',{node_id:topic.id,content:$('#new-statement-text').value,reason:$('#new-statement-reason').value});$('#modal').close();await route()}
 if(b.id==='submit-input'){await api('input',{title:$('#input-title').value,content:$('#input-content').value,node:$('#input-node').value});toast('Input archiviert.');go('sources')}
 if(b.id==='disconnect'){await api('chatgpt/disconnect',{});await route()}
}));
window.addEventListener('hashchange',()=>safely(route));
safely(async()=>{const s=await api('status');if(s.email){$('#login').hidden=true;$('#workspace').hidden=false;$('#user').textContent=s.email;await route()}else if(!s.google_ready){$('#google').removeAttribute('href');$('#google').textContent='Google-Anmeldung wird eingerichtet'}});
// Keep project-wide questions discoverable without replacing an active editor.
setInterval(()=>safely(async()=>{if(!G||document.hidden||$('#workspace').hidden)return;const fresh=await api('work-questions');const before=JSON.stringify(questions.map(q=>[q.id,q.version])),after=JSON.stringify(fresh.map(q=>[q.id,q.version]));if(before!==after){questions=fresh;if(current.page==='dashboard')dashboard(current.id);$('#questioncount').textContent=fresh.filter(q=>isOpen(q)).length;toast('Offene Fragen im Projekt wurden aktualisiert. Du findest sie links unter „Offene Fragen“.')}}),30000);

document.addEventListener('change',e=>{if(e.target.id==='record-decide'){$('[data-record-confirm]').textContent=e.target.checked?'Ergebnis beschließen & Frage klären':'Antwort übernehmen & Frage klären'}});

setInterval(()=>safely(async()=>{if(!G||document.hidden||$('#workspace').hidden)return;const fresh=await api('impact');const before=JSON.stringify(impactData),after=JSON.stringify(fresh);if(before!==after){impactData=fresh;$('#impactcount').textContent=fresh.findings.length+reconcileCount();if(current.page==='dashboard')dashboard(current.id);if(current.page==='impact'&&!$('#modal').open)await route();if(fresh.findings.length)toast('Neue oder aktualisierte KI-Prüfhinweise sind verfügbar. Öffne „KI-Prüfhinweise“.')}}),10000);
